INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l73',2,10,73,'The record-holder','纪录保持者','KS1/25/49 简单句·并列句·复合句复习(教材 L73 Key structures):用连词把句子连成简单句/并列句/复合句——who·whose(定语)、when·as、after+分词、although·in spite of the fact that、not only...but...as well、such...that、before;辅以课文被动语态复习(was given / was picked up / wasn''t noticed by anyone)与词汇辨析 evade/ashamed/imagination','逃学的孩子们都缺乏想象力。他们通常能做到的,至多也就是安静地钓上一天鱼,或在电影院里连着看上8个小时同一部电影。而有那么一个小男孩,他在逃学期间旅行了1600英里,使上述所有逃学的孩子都相形见绌。他搭便车到了多佛,天快黑时钻进了一条船,想找个地方睡觉。第二天早上他醒来时,发现船在这段时间已经到了加莱。当男孩从船里爬出来时,谁也没有发现他。从那里他又搭卡车到了巴黎。司机给了他几块饼干和一杯咖啡,就把他丢在了城外。男孩截住的下一辆车,没有像他希望的那样把他带到巴黎市中心,而是把他带到了法国和西班牙边界上的佩皮尼昂。他在那儿被一个警察抓住了,之后被当局送回了英国。他无疑为成千上万梦想逃避上学的孩子们创造了一项纪录。','{"q":"Listen and answer — Did the boy go where he wanted to?","options":["No — he wanted the center of Paris but ended up at Perpignan on the border","Yes — he reached the center of Paris","Yes — he went straight home","No — he never left England"],"answer_index":0}'::jsonb,'{"title":"KS1/25/49 简单句·并列句·复合句复习","intro":"本课复习“用连词把几句话连成一句”:①who/whose——把“人”和对他的描述连起来(a boy who traveled 1,600 miles;the man whose book was published);②when/as——“当…时”(When he woke up… / as he crept off);③after + 分词——“被…之后”(After being picked up…);④although / in spite of the fact that——“尽管”;⑤not only…but…as well——“不仅…而且”;⑥such…that——“如此…以致”;⑦before——“在…之前”。另配课文被动复习:was given / was picked up / wasn''t noticed by anyone。","table":{"headers":["连词","作用与例子"],"rows":[["who / whose","连接人与描述:a boy who traveled 1,600 miles"],["when / as","表时间:When he woke up… / as he crept off"],["although / in spite of the fact that","表尽管:Although the police searched everywhere…"],["not only…but…as well","表递进:not only reached the top but spent the night as well"],["such…that / before","such a fright that… / before help arrived"]]},"specialRules":[{"rule":"美语里“卡车”说 truck(英式 lorry)、“饼干”说 cookie(英式 biscuit)、“电影院”说 movie theater(英式 cinema)、“电影”说 movie(英式 film);本课已按美语改写课文。","mark":"truck/cookie/movie"},{"rule":"词汇辨析:evade=逃避、逃离(=escape);ashamed=感到羞愧(shameful=可耻的,修饰事);imagination=想象力(名词)。","mark":"evade/ashamed"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l73',1,NULL,'Children who play truant from school are unimaginative. A quiet day''s fishing, or eight hours in a movie theater seeing the same movie over and over again, is usually as far as they get.','逃学的孩子们都缺乏想象力。他们通常能做到的,至多也就是安静地钓上一天鱼,或在电影院里连着看上8个小时同一部电影。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l73',2,NULL,'They have all been put to shame by a boy who, while playing truant, traveled 1,600 miles. He hitchhiked to Dover and, toward evening, went into a boat to find somewhere to sleep.','而有那么一个小男孩,他在逃学期间旅行了1600英里,使上述所有逃学的孩子都相形见绌。他搭便车到了多佛,天快黑时钻进了一条船,想找个地方睡觉。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l73',3,NULL,'When he woke up next morning, he discovered that the boat had, in the meantime, traveled to Calais. No one noticed the boy as he crept off. From there, he hitchhiked to Paris in a truck.','第二天早上他醒来时,发现船在这段时间已经到了加莱。当男孩从船里爬出来时,谁也没有发现他。从那里他又搭卡车到了巴黎。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l73',4,NULL,'The driver gave him a few cookies and a cup of coffee and left him just outside the city. The next car the boy stopped did not take him into the center of Paris as he hoped it would, but to Perpignan on the French-Spanish border.','司机给了他几块饼干和一杯咖啡,就把他丢在了城外。男孩截住的下一辆车,没有像他希望的那样把他带到巴黎市中心,而是把他带到了法国和西班牙边界上的佩皮尼昂。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l73',5,NULL,'There he was picked up by a policeman and sent back to England by the local authorities. He has surely set up a record for the thousands of children who dream of evading school.','他在那儿被一个警察抓住了,之后被当局送回了英国。他无疑为成千上万梦想逃避上学的孩子们创造了一项纪录。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
