INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l73','put sb to shame','',NULL,'/pʊt tə ʃeɪm/','They were all put to shame by a boy who traveled 1,600 miles.','他们都被一个走了1600英里的男孩比得相形见绌。','Her hard work put the rest of us to shame.','她的勤奋让我们其余人都自愧不如。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l73','as far as sb gets','',NULL,'/æz fɑːr æz ɡets/','A quiet day''s fishing is usually as far as they get.','安静地钓一天鱼,至多也就到这个程度了。','A short walk is as far as he gets these days.','如今他至多也就散散步。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l73','set up a record','',NULL,'/set ʌp ə ˈrekərd/','He has surely set up a record.','他无疑创造了一项纪录。','The young runner set up a new record.','这位年轻跑者创造了一项新纪录。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l73','dream of doing','',NULL,'/driːm əv ˈduːɪŋ/','Thousands of children dream of evading school.','成千上万的孩子梦想逃学。','She dreams of traveling around the world.','她梦想环游世界。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l73',5,'am2_l73_gp1','choice','{"stem":"\"Children ___ play truant from school are unimaginative.\"(用连词把“孩子”和“逃学”连起来,指人作主语)","options":["whose","who","whom","which"],"answer_index":1,"stem_cn":"逃学的孩子缺乏想象力。","explanation_cn":"指“人”并在后半句里作主语时,用 who 把两句连成一句。✓ Children who play truant are unimaginative. ✗ which:指物;✗ whose:表“谁的”;✗ whom:作宾格,此处需要主格。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l73',5,'am2_l73_gp1','choice','{"stem":"\"They were put to shame by a boy ___ traveled 1,600 miles.\"(指人作主语的连词)","options":["where","whose","who","which"],"answer_index":2,"stem_cn":"他们都被一个走了1600英里的男孩比得相形见绌。","explanation_cn":"指“人(a boy)”且在从句里作主语,用 who。✓ a boy who traveled 1,600 miles. ✗ which:指物;✗ whose:表所属;✗ where:指地点。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l73',5,'am2_l73_gp1','choice','{"stem":"\"James Sullivan, ___ book was published recently, will give a lecture.\"(表“他的书”的所属连词)","options":["who is","whose","who","which"],"answer_index":1,"stem_cn":"詹姆斯·沙利文将做讲座,他的书最近刚出版。","explanation_cn":"表“他的书(book 属于 James)”用 whose。✓ James Sullivan, whose book was published recently… ✗ who:作主语,不表所属;✗ which:指物且不表所属;✗ who is:是“他是”,意思不对。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l73',5,'am2_l73_gp2','choice','{"stem":"\"___ he woke up next morning, he discovered the boat had traveled to Calais.\"(“当…时”的时间连词)","options":["What","Who","Which","When"],"answer_index":3,"stem_cn":"第二天早上他醒来时,发现船已开到了加莱。","explanation_cn":"“当…的时候”用 When 引出时间。✓ When he woke up next morning, he discovered… ✗ Which:指物;✗ What:表“什么”;✗ Who:表“谁”。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l73',5,'am2_l73_gp2','choice','{"stem":"\"No one noticed the boy ___ he crept off the boat.\"(“正当…时”的连词)","options":["for","or","as","so"],"answer_index":2,"stem_cn":"男孩溜下船时,没人注意到他。","explanation_cn":"“正当…的时候、一边…一边”用 as。✓ No one noticed the boy as he crept off. ✗ so:表“所以”;✗ or:表“或者”;✗ for:表“因为”。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l73',5,'am2_l73_gp2','choice','{"stem":"\"___ picked up by a policeman, he was sent back to England.\"(用“被…之后”的分词短语开头)","options":["After being","After been","After he picked up","After picking up"],"answer_index":0,"stem_cn":"被警察带走后,他被送回了英国。","explanation_cn":"“被…之后”用 After being + 过去分词(被动的分词短语)。✓ After being picked up by a policeman, he was sent back. ✗ After he picked up:意思成了“他捡起”,不是“他被带走”;✗ After picking up:主动,意思反了;✗ After been:缺 being。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l73',5,'am2_l73_gp3','choice','{"stem":"\"___ the police searched everywhere, the missing boy could not be found.\"(“尽管”的让步连词)","options":["Unless","So","Although","Because"],"answer_index":2,"stem_cn":"尽管警察到处搜寻,还是找不到那个失踪的男孩。","explanation_cn":"“尽管、虽然”用 Although 引出让步。✓ Although the police searched everywhere, the boy could not be found. ✗ Because:表原因;✗ So:表结果;✗ Unless:表“除非”。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l73',5,'am2_l73_gp3','choice','{"stem":"\"In spite of the fact ___ fares have increased, the company is still losing money.\"(引出后面的说明内容)","options":["why","what","which","that"],"answer_index":3,"stem_cn":"尽管票价上涨,公司仍在亏损。","explanation_cn":"“In spite of the fact ___”后面用 that 引出要说明的事实。✓ In spite of the fact that fares have increased… ✗ which/what/why:都不能这样引出 fact 后的说明内容。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l73',5,'am2_l73_gp3','choice','{"stem":"\"___ very tired, he kept on walking.\"(“尽管…”的让步连词,后接形容词)","options":["So","Because","Though","Unless"],"answer_index":2,"stem_cn":"尽管很累,他还是继续往前走。","explanation_cn":"“尽管…”用 Though,后面可直接接形容词(Though very tired)。✓ Though very tired, he kept on walking. ✗ Because:表原因;✗ So:表结果;✗ Unless:表“除非”。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l73',5,'am2_l73_gp4','choice','{"stem":"\"The climbers ___ reached the top but spent the night there as well.\"(“不仅…而且”的前半)","options":["not only","neither","only","either"],"answer_index":0,"stem_cn":"登山者不仅登了顶,还在那里过了夜。","explanation_cn":"“不仅…而且…as well”的前半用 not only。✓ The climbers not only reached the top but spent the night there as well. ✗ only:少了 not,不成“不仅…而且”;✗ either / neither:与 but…as well 搭配不上。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l73',5,'am2_l73_gp4','choice','{"stem":"\"He gave me ___ a fright that I knocked the teapot over.\"(“如此…以致”:接名词短语用哪个词)","options":["very","so","such","too"],"answer_index":2,"stem_cn":"他把我吓了一大跳,我把茶壶都碰翻了。","explanation_cn":"后面接“a fright(名词短语)”时,“如此…以致”用 such…that。✓ He gave me such a fright that I knocked the teapot over. ✗ so:so 后接形容词/副词(so frightened),不接名词短语;✗ very / too:构不成“如此…以致”的结构。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l73',5,'am2_l73_gp4','choice','{"stem":"\"He fought the wolves off for three hours ___ help arrived.\"(“在…之前”的时间连词)","options":["since","until","after","before"],"answer_index":3,"stem_cn":"在救援到来之前,他与狼搏斗了三个小时。","explanation_cn":"“在…之前”用 before。✓ He fought the wolves off for three hours before help arrived. ✗ after:表“之后”;✗ since:表“自从”;✗ until:表“直到”,与此处“救援到来之前一直搏斗”语义不同。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l73',5,'am2_l73_gp5','choice','{"stem":"\"The boy ___ a few cookies by the driver.\"(被动:被给了几块饼干)","options":["has given","was given","was giving","gave"],"answer_index":1,"stem_cn":"男孩被司机给了几块饼干。","explanation_cn":"“(某人)被给了某物”用 was given + 物(被动)。✓ The boy was given a few cookies by the driver. ✗ gave:主动,意思成了“男孩给”;✗ was giving:进行,不合;✗ has given:现在完成主动。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l73',5,'am2_l73_gp5','choice','{"stem":"\"There he ___ by a policeman and sent back to England.\"(一般过去被动:被带走)","options":["was picked up","picked up","was picking up","has picked up"],"answer_index":0,"stem_cn":"在那儿他被一名警察带走,并被送回了英国。","explanation_cn":"一般过去的被动 = was + 过去分词。✓ There he was picked up by a policeman. ✗ picked up:主动,意思成了“他抓住”;✗ was picking up:进行主动;✗ has picked up:现在完成主动。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l73',5,'am2_l73_gp5','choice','{"stem":"\"He crept off the boat and ___ by anyone.\"(否定被动:没被任何人注意到)","options":["hasn''t noticed","didn''t notice","wasn''t noticed","wasn''t noticing"],"answer_index":2,"stem_cn":"他溜下了船,没被任何人注意到。","explanation_cn":"“没被(任何人)注意到”用否定的被动 wasn''t noticed(by anyone)。✓ He crept off and wasn''t noticed by anyone. ✗ didn''t notice:主动,意思成了“他没注意到”;✗ wasn''t noticing:进行;✗ hasn''t noticed:现在完成主动。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l73',5,'am2_l73_gp6','choice','{"stem":"\"Thousands of children dream of ___ school.\"(逃避、逃学用哪个词)","options":["refusing","evading","denying","preventing"],"answer_index":1,"stem_cn":"成千上万的孩子梦想逃学。","explanation_cn":"“逃避、逃学”用 evade,其 -ing 形式 evading 作 of 的宾语。✓ Thousands of children dream of evading school. ✗ preventing:是“阻止”;✗ refusing:是“拒绝”;✗ denying:是“否认”。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l73',5,'am2_l73_gp6','choice','{"stem":"\"They have been put to shame; they should feel ___.\"(感到羞愧用哪个词)","options":["ashamed","shameful","shame","shyness"],"answer_index":0,"stem_cn":"他们被比得很难堪,应该感到羞愧。","explanation_cn":"“(人)感到羞愧”用 ashamed(feel ashamed)。✓ They should feel ashamed. ✗ shameful:是“可耻的”,修饰“事”不修饰“人的感受”;✗ shame:是名词;✗ shyness:是“害羞、腼腆”,意思不同。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l73',5,'am2_l73_gp6','choice','{"stem":"\"They haven''t much ___; that''s why they are unimaginative.\"(缺乏“想象力”这个名词)","options":["imaginary","imagination","image","imaginative"],"answer_index":1,"stem_cn":"他们缺乏想象力,所以做事没新意。","explanation_cn":"“想象力(名词)”用 imagination,haven''t much + 名词。✓ They haven''t much imagination. ✗ imaginary:是“虚构的(形容词)”;✗ imaginative:是“富有想象力的(形容词)”;✗ image:是“形象、图像”。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l73',6,NULL,'choice','{"stem":"美语里\"卡车\"常说:","options":["load-car","truck","lorry","big-car"],"answer_index":1,"explanation_cn":"美语“卡车”说 truck;英式说 lorry。✓ He hitchhiked to Paris in a truck. 他搭一辆卡车到了巴黎。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l73',6,NULL,'choice','{"stem":"美语里\"饼干\"常说:","options":["sweet-bread","bread-cake","cookie","biscuit"],"answer_index":2,"explanation_cn":"美语“饼干”说 cookie;英式说 biscuit。✓ The driver gave him a few cookies. 司机给了他几块饼干。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l73',6,NULL,'choice','{"stem":"truant 的意思是:","options":["老师","逃学的孩子","校长","优等生"],"answer_index":1,"explanation_cn":"truant = 逃学的孩子;play truant = 逃学。✓ Children who play truant are unimaginative 逃学的孩子缺乏想象力。\n顺带记:优等生 = top student;老师 = teacher;校长 = principal."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l73',6,NULL,'choice','{"stem":"hitchhike 的意思是:","options":["徒步登山","乘船出海","搭便车旅行","骑车比赛"],"answer_index":2,"explanation_cn":"hitchhike = 搭便车旅行。✓ He hitchhiked to Dover 他搭便车到了多佛。\n顺带记:徒步登山 = hike;骑车比赛 = cycle race;乘船出海 = sail out."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l73',6,NULL,'choice','{"stem":"evade 的意思是:","options":["逃避,逃离","参加","完成","面对"],"answer_index":0,"explanation_cn":"evade = 逃避、逃离(≈escape)。✓ dream of evading school 梦想逃学。\n顺带记:面对 = face;参加 = join;完成 = finish."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l73',6,NULL,'choice','{"stem":"shame 的意思是:","options":["骄傲","惭愧,羞耻","快乐","愤怒"],"answer_index":1,"explanation_cn":"shame = 惭愧、羞耻;put sb to shame = 使某人相形见绌。✓ put to shame by a boy 被一个男孩比得难堪。\n顺带记:骄傲 = pride;快乐 = joy;愤怒 = anger."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l73',7,NULL,'cloze','{"stem":"第 1 空","context":"Children ___1___ play truant are unimaginative. One boy, however, traveled 1,600 miles. ___2___ he woke up on the boat, he found it had crossed to Calais. He hitchhiked to Paris in a truck, and later ___3___ picked up by a policeman. He has surely ___4___ up a record.","blank_no":1,"options":["who","which","whose","where"],"answer_index":0,"explanation_cn":"指“人(children)”并作主语,用 who 连接。✓ Children who play truant are unimaginative.\n✗ which:指物;✗ whose:表所属;✗ where:指地点。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l73',7,NULL,'cloze','{"stem":"第 2 空","context":"Children ___1___ play truant are unimaginative. One boy, however, traveled 1,600 miles. ___2___ he woke up on the boat, he found it had crossed to Calais. He hitchhiked to Paris in a truck, and later ___3___ picked up by a policeman. He has surely ___4___ up a record.","blank_no":2,"options":["When","Which","What","Who"],"answer_index":0,"explanation_cn":"“当…时”用 When 引出时间。✓ When he woke up on the boat, he found it had crossed to Calais.\n✗ Which / What / Who:都不表时间。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l73',7,NULL,'cloze','{"stem":"第 3 空","context":"Children ___1___ play truant are unimaginative. One boy, however, traveled 1,600 miles. ___2___ he woke up on the boat, he found it had crossed to Calais. He hitchhiked to Paris in a truck, and later ___3___ picked up by a policeman. He has surely ___4___ up a record.","blank_no":3,"options":["was","were","is","has"],"answer_index":0,"explanation_cn":"一般过去的被动“was picked up”,此处用 was。✓ later he was picked up by a policeman.\n✗ were:单数主语不用 were;✗ is / has:时态/结构不合。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l73',7,NULL,'cloze','{"stem":"第 4 空","context":"Children ___1___ play truant are unimaginative. One boy, however, traveled 1,600 miles. ___2___ he woke up on the boat, he found it had crossed to Calais. He hitchhiked to Paris in a truck, and later ___3___ picked up by a policeman. He has surely ___4___ up a record.","blank_no":4,"options":["set","sat","put","made"],"answer_index":0,"explanation_cn":"“创造纪录”用 set up a record,set 三态同形。✓ He has surely set up a record.\n✗ sat:是 sit(坐)的过去式;✗ put:不与 up a record 搭配成“创造纪录”;✗ made:不与 set up 一样搭配。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l73',8,NULL,'choice','{"stem":"What do children who play truant usually do, according to the passage?","options":["Help their parents at work","Read books at the library","Travel to other countries","Go fishing or sit in a movie theater watching the same movie"],"answer_index":3,"explanation_cn":"课文说 A quiet day''s fishing, or eight hours in a movie theater seeing the same movie… is usually as far as they get。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l73',8,NULL,'choice','{"stem":"How far did this one boy travel while playing truant?","options":["About 16 miles","About 1,600 miles","About 6,000 miles","About 160 miles"],"answer_index":1,"explanation_cn":"课文说 a boy who, while playing truant, traveled 1,600 miles。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l73',8,NULL,'choice','{"stem":"Where was the boy finally picked up, and by whom?","options":["In Calais, by a sailor","In Paris, by a driver","At Perpignan, by a policeman","In Dover, by his father"],"answer_index":2,"explanation_cn":"课文说 …to Perpignan on the French-Spanish border. There he was picked up by a policeman。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l73',9,NULL,'choice','{"stem":"你想说\"逃学的孩子缺乏想象力\"(用 who 把两句话连成一句):","options":["Children who play truant are unimaginative.","Children whose play truant are unimaginative.","Children which play truant are unimaginative.","Children where play truant are unimaginative."],"answer_index":0,"explanation_cn":"用 who 把“孩子”和“逃学”连成一句(who 指人)。✓ Children who play truant are unimaginative. 场合:描述“做某事的那类人”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l73',9,NULL,'choice','{"stem":"你想说\"被警察带走后,他被送回了英国\"(过去被动):","options":["After being pick up by a policeman, he was sent back to England.","After being picked up by a policeman, he sent back to England.","After being picked up by a policeman, he was sent back to England.","After picked up by a policeman, he was sent back to England."],"answer_index":2,"explanation_cn":"“被…之后”用 After being + 过去分词;主句“被送回”也用被动 was sent。✓ After being picked up by a policeman, he was sent back to England. 场合:讲一件被动发生、随后又被处理的事。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l73',9,NULL,'choice','{"stem":"你想说\"尽管警察到处搜寻,还是没找到那个男孩\"(用 although 表尽管):","options":["Because the police searched everywhere, the boy could not be found.","Although the police searched everywhere, but the boy could not be found.","So the police searched everywhere, the boy could not be found.","Although the police searched everywhere, the boy could not be found."],"answer_index":3,"explanation_cn":"“尽管”用 Although 引出让步,且后面主句不再加 but。✓ Although the police searched everywhere, the boy could not be found. 场合:说“尽管做了努力,结果却…”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l73',10,NULL,'choice','{"stem":"evade 的意思是:","options":["面对","完成","参加","逃避,逃离"],"answer_index":3,"explanation_cn":"evade = 逃避、逃离(≈escape)。✓ dream of evading school 梦想逃学。\n顺带记:面对 = face;参加 = join;完成 = finish."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l73',10,NULL,'choice','{"stem":"truant 的意思是:","options":["逃学的孩子","优等生","老师","校长"],"answer_index":0,"explanation_cn":"truant = 逃学的孩子。✓ Children who play truant 逃学的孩子。\n顺带记:优等生 = top student;老师 = teacher;校长 = principal."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l73',10,NULL,'choice','{"stem":"\"Children ___ play truant are unimaginative.\"(指人、把两句连起来)","options":["where","which","whose","who"],"answer_index":3,"stem_cn":"逃学的孩子缺乏想象力。","explanation_cn":"指“人”并作主语,用 who 把两句连起来。✓ Children who play truant are unimaginative.\n✗ which:指物;✗ whose:表所属;✗ where:指地点。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l73',10,NULL,'choice','{"stem":"\"There he ___ by a policeman and sent back to England.\"(一般过去被动)","options":["picked up","was picking up","was picked up","has picked up"],"answer_index":2,"stem_cn":"在那儿他被一名警察带走。","explanation_cn":"一般过去的被动 = was + 过去分词。✓ There he was picked up by a policeman.\n✗ picked up:主动;✗ was picking up:进行;✗ has picked up:现在完成。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l73',10,NULL,'choice','{"stem":"\"put sb to shame\" 的意思是:","options":["当众批评某人","羞辱并伤害某人","向某人道歉","使某人相形见绌、自愧不如"],"answer_index":3,"explanation_cn":"put sb to shame = 因为自己做得更好而使某人相形见绌、自愧不如。如 The boy put all other truants to shame。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l73',10,NULL,'choice','{"stem":"although 这个词表示的意思是:","options":["所以","尽管、虽然","如果","因为"],"answer_index":1,"explanation_cn":"although = 尽管、虽然,引出让步;后面主句不再加 but。如 Although it rained, we went out。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l73',10,NULL,'choice','{"stem":"How did the boy get from Dover across the water to Calais?","options":["He fell asleep in a boat that crossed over during the night","He walked over a bridge","He swam across the sea","He flew in a small plane"],"answer_index":0,"passage":"Children who play truant from school are unimaginative. A quiet day''s fishing, or eight hours in a movie theater seeing the same movie over and over again, is usually as far as they get. They have all been put to shame by a boy who, while playing truant, traveled 1,600 miles. He hitchhiked to Dover and, toward evening, went into a boat to find somewhere to sleep. When he woke up next morning, he discovered that the boat had, in the meantime, traveled to Calais. No one noticed the boy as he crept off. From there, he hitchhiked to Paris in a truck. The driver gave him a few cookies and a cup of coffee and left him just outside the city. The next car the boy stopped did not take him into the center of Paris as he hoped it would, but to Perpignan on the French-Spanish border. There he was picked up by a policeman and sent back to England by the local authorities. He has surely set up a record for the thousands of children who dream of evading school.","explanation_cn":"课文说 he went into a boat to find somewhere to sleep… the boat had, in the meantime, traveled to Calais。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l73',10,NULL,'choice','{"stem":"Why is the boy called a record-holder?","options":["He built the fastest car","He traveled 1,600 miles while playing truant, farther than any other truant","He won a school race","He read the most books in his class"],"answer_index":1,"passage":"Children who play truant from school are unimaginative. A quiet day''s fishing, or eight hours in a movie theater seeing the same movie over and over again, is usually as far as they get. They have all been put to shame by a boy who, while playing truant, traveled 1,600 miles. He hitchhiked to Dover and, toward evening, went into a boat to find somewhere to sleep. When he woke up next morning, he discovered that the boat had, in the meantime, traveled to Calais. No one noticed the boy as he crept off. From there, he hitchhiked to Paris in a truck. The driver gave him a few cookies and a cup of coffee and left him just outside the city. The next car the boy stopped did not take him into the center of Paris as he hoped it would, but to Perpignan on the French-Spanish border. There he was picked up by a policeman and sent back to England by the local authorities. He has surely set up a record for the thousands of children who dream of evading school.","explanation_cn":"课文说 They have all been put to shame by a boy who… traveled 1,600 miles… He has surely set up a record。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l73',10,NULL,'choice','{"stem":"How far did the boy travel?","options":["About 60 miles","About 16 miles","About 600 miles","About 1,600 miles"],"answer_index":3,"audio":"Children who play truant from school are unimaginative. A quiet day''s fishing, or eight hours in a movie theater seeing the same movie over and over again, is usually as far as they get. They have all been put to shame by a boy who, while playing truant, traveled 1,600 miles. He hitchhiked to Dover and, toward evening, went into a boat to find somewhere to sleep. When he woke up next morning, he discovered that the boat had, in the meantime, traveled to Calais. No one noticed the boy as he crept off. From there, he hitchhiked to Paris in a truck. The driver gave him a few cookies and a cup of coffee and left him just outside the city. The next car the boy stopped did not take him into the center of Paris as he hoped it would, but to Perpignan on the French-Spanish border. There he was picked up by a policeman and sent back to England by the local authorities. He has surely set up a record for the thousands of children who dream of evading school.","explanation_cn":"课文说 a boy who… traveled 1,600 miles。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l73',10,NULL,'choice','{"stem":"Who picked the boy up in the end?","options":["A truck driver in Paris","A sailor on the boat","A policeman at Perpignan","His father at Dover"],"answer_index":2,"audio":"Children who play truant from school are unimaginative. A quiet day''s fishing, or eight hours in a movie theater seeing the same movie over and over again, is usually as far as they get. They have all been put to shame by a boy who, while playing truant, traveled 1,600 miles. He hitchhiked to Dover and, toward evening, went into a boat to find somewhere to sleep. When he woke up next morning, he discovered that the boat had, in the meantime, traveled to Calais. No one noticed the boy as he crept off. From there, he hitchhiked to Paris in a truck. The driver gave him a few cookies and a cup of coffee and left him just outside the city. The next car the boy stopped did not take him into the center of Paris as he hoped it would, but to Perpignan on the French-Spanish border. There he was picked up by a policeman and sent back to England by the local authorities. He has surely set up a record for the thousands of children who dream of evading school.","explanation_cn":"课文说 …to Perpignan… There he was picked up by a policeman。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
